// InfracostCommandProperties holds properties for the infracost-command event.
type InfracostCommandProperties struct {
	// The command's own name, e.g. `setup` or `login`, not its path. Two different
	// commands can share a name, so segment on `commandPath`.
	Command string `json:"command"`

	// The full invoked command path, e.g. `infracost setup` or `infracost auth
	// login`.
	CommandPath *string `json:"commandPath,omitempty"`

	// True if the command exited cleanly, false if it returned an error.
	Success bool `json:"success"`

	// Wall-clock time the command took to complete, in seconds.
	DurationSeconds float64 `json:"durationSeconds"`

	// Sanitized error message, truncated to 200 characters. Set only when
	// `success` is false, and never for `infracost setup` or `infracost ci setup`,
	// whose raw errors name local paths and user config; those report `errorKind`
	// instead.
	ErrorMessage *string `json:"errorMessage,omitempty"`

	// Bounded error label, in place of `errorMessage` for `infracost setup` and
	// `infracost ci setup`. Classifying rather than dropping means a failure
	// before those commands emit their own outcome event still says something.
	ErrorKind *InfracostCommandErrorKind `json:"errorKind,omitempty"`
}

// TrackInfracostCommand tracks the infracost-command event.
//
// Sent by the v2 CLI (infracost/cli) for every command other than `scan`,
// `price` and `inspect` — those three fire `infracost-run` / `infracost-error`
// instead as the v2 successors to v1's `breakdown` / `diff`. Covers `agent`,
// `auth`, `budgets`, `ci`, `doctor`, `guardrails`, `ide`, `login`, `logout`,
// `org`, `policies`, `setup`, `update`, `version` and `whoami`, firing on both
// success and failure. Also inherits the standard CLI global metadata
// (`version`, `fullVersion`, `isDev`, `isTest`, `os`, `arch`, `installId`,
// `caller`, `cliPlatform`, `ciPlatform`, `flags`, `flagValues`).
func TrackInfracostCommand(ctx context.Context, client AnalyticsClient, props InfracostCommandProperties) error {
	return client.Track(ctx, EventInfracostCommand, props)
}

