// TrackInfracostComment tracks the infracost-comment event.
//
// Sent when `infracost comment` is run, with a subset of the `infracost-run`
// properties plus the policy counts below. Emitted by the v1 CLI
// (infracost/infracost) comment commands for GitHub, GitLab, Bitbucket and
// Azure Repos.
func TrackInfracostComment(ctx context.Context, client AnalyticsClient, props InfracostCommentProperties) error {
	return client.Track(ctx, EventInfracostComment, props)
}

// InfracostErrorProperties holds properties for the infracost-error event.
type InfracostErrorProperties struct {
	// The sanitized error message for the failure. On a panic this is the panic
	// value, reduced to just its Go type for `infracost setup` and `infracost ci
	// setup`, whose panic values can carry the local path or config that panicked.
	Error *string `json:"error,omitempty"`

	// Sanitized Go stack trace, set only on a v2 CLI panic. Absolute paths,
	// function arguments and goroutine numbers are stripped, so equivalent panics
	// produce an identical string and can be grouped. Empty when the trace could
	// not be parsed.
	Stacktrace *string `json:"stacktrace,omitempty"`

	// Wall-clock time the run took before it failed, in seconds. Set by the v2 CLI
	// for `scan`, `diff` and `inspect`.
	RunSeconds *float64 `json:"runSeconds,omitempty"`

	// The output format of the failed run, with the same meaning as `outputFormat`
	// on `infracost-run` for the same emitter.
	OutputFormat *string `json:"outputFormat,omitempty"`
}

// TrackInfracostError tracks the infracost-error event.
//
// Sent for each unsuccessful run of `infracost breakdown`, `diff`, `scan`,
// `price` or `inspect`. Sends a subset of the `infracost-run` properties,
// dependent on when in the run the error occurred. Emitted by the v1 CLI
// (infracost/infracost), the v2 CLI (infracost/cli), the CI scanner
// (infracost/ci) and the Infracost Cloud PR runner. The v2 CLI also sends it
// for a critical startup diagnostic and for a panic.
func TrackInfracostError(ctx context.Context, client AnalyticsClient, props InfracostErrorProperties) error {
	return client.Track(ctx, EventInfracostError, props)
}

